"""Deterministic mock output for the Deployment Agent (tests and offline demos only)."""

import re


def deploy_message(system: str, user: str) -> dict:
    ids = sorted(set(re.findall(r"\b(?:N?FR)-\d{3}\b", user)))
    bullets = "".join(f"\n- {i}" for i in ids)
    return {
        "summary": "[Mock] Commit message written.",
        "message": f"Add the implementation generated by Ampera\n{bullets}",
    }
